        );
      }
      snap(
        "完成",
        `合并完成：[${ls[0].join(", ")}]。一共 ${round} 轮，每轮每个节点只被处理一次，所以是 O(n log k)。`,
        view([], 0, null, false),
        { at: "done", kind: "ok", ans: ls[0].slice(), facts: [["总轮次", round], ["最终长度", ls[0].length]] },
      );
    }

